begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir fixtures/duinpad-finalists.inc
create temp table finale_state(result jsonb,first_scan timestamptz,deadline timestamptz);
insert into finale_state values('{}',null,null);
grant all on finale_state to authenticated;
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is(api.duinpad_finale_snapshot('duindorp-halloween-2026')->>'eligible','true','own account can see the server released finale');
select is(jsonb_array_length(api.duinpad_finale_snapshot('duindorp-halloween-2026')->'children'),2,'party scopes only its two present children');
select is(api.duinpad_finale_validate('duindorp-halloween-2026','DUINPAD-SIM-FINALE-TOKEN')->>'valid','true','validating the real final credential is allowed');
set local role postgres;
select is((select count(*) from app_private.duinpad_finale_receipts),0::bigint,'validation consumes no scan');
select is((select count(*) from app_private.duinpad_evenings),0::bigint,'validation starts no clock');
set local role authenticated;
select throws_ok($$select api.duinpad_finale_confirm('duindorp-halloween-2026','DUINPAD-SIM-FINALE-TOKEN','{"d9000000-0000-0000-0000-000000000003":"visited"}','foreign-child')$$,'22023','INVALID_ATTENDANCE','a party cannot decide the standalone child');
update finale_state set result=api.duinpad_finale_confirm('duindorp-halloween-2026','DUINPAD-SIM-FINALE-TOKEN','{"d9000000-0000-0000-0000-000000000001":"visited","d9000000-0000-0000-0000-000000000002":"skipped"}','first-finale');
select is((select result->>'duplicate' from finale_state),'false','first confirmed arrival records the party');
select is(api.duinpad_finale_confirm('duindorp-halloween-2026','DUINPAD-SIM-FINALE-TOKEN','{}','first-finale')->>'duplicate','true','duplicate returns own receipt even after currentStop is empty');
set local role postgres;
update finale_state set first_scan=(select first_finale_scan_at from app_private.duinpad_evenings),deadline=(select evening_ends_at from app_private.duinpad_evenings);
select is((select deadline-first_scan from finale_state),interval '2 hours','deadline equals exactly first durable scan plus two hours');
select is((select status::text from app_private.group_runs where id='d8000000-0000-0000-0000-000000000001'),'completed','physical route completes immediately');
select is((select status::text from app_private.portal_reservations where id='da000000-0000-0000-0000-000000000001'),'completed','final capacity completes immediately');
select is((select count(*) from app_private.run_stop_arrivals where run_id='d8000000-0000-0000-0000-000000000001'),2::bigint,'only the explicitly confirmed party has arrival proof');
select is((select count(*) from app_private.poortenboek_passport_seals where run_id='d8000000-0000-0000-0000-000000000001'),2::bigint,'present child skipping the experience still receives a seal');
select is((select count(*) from app_private.duinpad_evening_members),4::bigint,'frozen cohort contains all four participating adults, including no-scan household');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is(api.duinpad_finale_confirm('duindorp-halloween-2026','bad-no-longer-needed','{}','party-repeat')->>'duplicate','true','second party account receives the same prior receipt');
select throws_ok($$select api.run_complete_stop('d8000000-0000-0000-0000-000000000001','db000000-0000-0000-0000-000000000001',1,true,'native-finale','native-finale')$$,'42501','NOT_AUTHORIZED','native finale endpoint does not open general leader permissions');
set local role postgres;
update app_private.together_memberships set left_at=clock_timestamp() where registration_id='d3000000-0000-0000-0000-000000000002';
set local role authenticated;
select is(api.duinpad_finale_snapshot('duindorp-halloween-2026')->>'recorded','true','party departure does not reset the used scan right');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select is(api.duinpad_finale_snapshot('duindorp-halloween-2026')->>'eligible','true','a later independent account can still scan the saved completed finalestop');
select is(api.duinpad_finale_confirm('duindorp-halloween-2026','DUINPAD-SIM-FINALE-TOKEN','{"d9000000-0000-0000-0000-000000000003":"skipped"}','later-finale')->>'duplicate','false','later standalone account gets its one scan');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
select is(api.duinpad_finale_confirm('duindorp-halloween-2026','DUINPAD-SIM-FINALE-TOKEN','{"d9000000-0000-0000-0000-000000000003":"visited"}','second-adult')->>'duplicate','false','without a party another adult retains its account-based scan unit');
select is(api.portal_thanks_snapshot('duindorp-halloween-2026')->>'finished','false','route completion alone does not prematurely open the closing screen');
set local role postgres;
select is((select evening_ends_at from app_private.duinpad_evenings),(select deadline from finale_state),'later scans never move the deadline');
select is((select count(*) from app_private.poortenboek_passport_seals where run_id='d8000000-0000-0000-0000-000000000001'),3::bigint,'later accounts add no duplicate seals');
select throws_ok($$update app_private.duinpad_evenings set evening_ends_at=evening_ends_at+interval '1 minute'$$,'23514','DUINPAD_HISTORY_IMMUTABLE','deadlines are immutable');
select throws_ok($$delete from app_private.duinpad_finale_receipts$$,'23514','DUINPAD_HISTORY_IMMUTABLE','receipts cannot be erased by local group reset');
select is(api.worker_duinpad_evenings()->>'processed','0','worker does not close an unexpired evening');
-- Move only synthetic frozen timestamps with the explicit fixture trigger off.
-- The production API exposes no clock override or correction command.
create function pg_temp.deadline_boundary(_delta interval) returns boolean language plpgsql security definer set search_path='' as $$
begin
 alter table app_private.duinpad_evenings disable trigger duinpad_evening_immutable;
 update app_private.duinpad_evenings set first_finale_scan_at=statement_timestamp()+_delta-interval '2 hours',evening_ends_at=statement_timestamp()+_delta;
 alter table app_private.duinpad_evenings enable trigger duinpad_evening_immutable;
 return(api.duinpad_finale_snapshot('duindorp-halloween-2026')->>'eveningEnded')::boolean;
end $$;
select is(pg_temp.deadline_boundary(interval '1 millisecond'),false,'one millisecond before the exact server deadline the evening remains open');
select is(pg_temp.deadline_boundary(interval '0'),true,'at the exact server deadline the evening is closed');
select is(pg_temp.deadline_boundary(interval '-1 millisecond'),true,'one millisecond after the exact server deadline the evening remains closed');
select set_config('request.jwt.claims','{"sub":"d1000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
set local role authenticated;
select is(api.duinpad_finale_snapshot('duindorp-halloween-2026')->>'eveningEnded','true','deadline is authoritative before worker polls, even at the exact boundary');
select is(api.portal_thanks_snapshot('duindorp-halloween-2026')->>'finished','true','thanks uses the same deadline without an open browser');
select lives_ok($$select api.portal_thanks_save('duindorp-halloween-2026',(api.duinpad_finale_snapshot('duindorp-halloween-2026')->>'portalId')::uuid,'welcome')$$,'confirmed final arrival permits only the own household thanks');
set local role postgres;
select is(api.worker_duinpad_evenings()->>'queued','4','deadline queues one transactional mail per participating adult');
select is(api.worker_duinpad_evenings()->>'queued','0','concurrent/repeated worker is idempotent');
select is((select count(*) from app_private.email_outbox where message_type='duinpad_evening_thanks'),4::bigint,'cohort mail dedupe remains durable per event/account');
select ok((select processed_at>=evening_ends_at from app_private.duinpad_evenings),'processing time remains separate from logical due time');
select * from finish();
rollback;
